{
"predictors": [
{
"name": "Employee Satisfaction Index",
"construction": "Survey data from third-party rating agencies regarding employee satisfaction, normalized by industry.",
"rationale": "Happier employees may contribute to a more productive and innovative company, leading to higher returns.",
"higher_returns_for": "High values of the measure"
},
{
"name": "CEO Tenure",
"construction": "Number of years the current CEO has been in position.",
"rationale": "CEOs with longer tenure could suggest stability and successful long-term strategy.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Website Traffic Growth",
"construction": "Percentage growth in unique website visits over the past quarter, using third-party web analytics data.",
"rationale": "Increasing website traffic could indicate growing interest in the company's products or services.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Corporate Social Responsibility Rating",
"construction": "Ratings from third-party agencies on a company's social responsibility, normalized by industry.",
"rationale": "Companies with strong social responsibility practices may be more resilient to social and regulatory risks.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Customer Churn",
"construction": "The percentage of customers lost over the past year, from company reports.",
"rationale": "High customer churn could indicate competitive weakness and lower future revenues.",
"higher_returns_for": "Low values of the measure"
},
{
"name": "Patent Portfolio Growth",
"construction": "Percentage growth in number of patents held by the company over the past year, from US Patent and Trademark Office data.",
"rationale": "Increasing patent portfolio could indicate a strong innovation pipeline and potential future growth.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Supply Chain Complexity",
"construction": "Number of unique suppliers, according to company financial disclosures.",
"rationale": "More complex supply chains may be more vulnerable to disruptions, negatively impacting future profitability.",
"higher_returns_for": "Low values of the measure"
},
{
"name": "R&D Expenditure Volatility",
"construction": "Standard deviation of monthly R&D expenditures over the past three years, from company financial disclosures.",
"rationale": "High volatility in R&D spending could indicate poor planning or execution in the company's innovation strategy.",
"higher_returns_for": "Low values of the measure"
},
{
"name": "Customer Concentration",
"construction": "Revenue from the largest customer as a percentage of total revenue, from company financial disclosures.",
"rationale": "High customer concentration may increase business risk due to over-reliance on a single customer.",
"higher_returns_for": "Low values of the measure"
},
{
"name": "Product Diversity",
"construction": "Number of distinct product lines, from company financial disclosures.",
"rationale": "Companies with a diverse range of products may be more resilient to industry-specific shocks.",
"higher_returns_for": "High values of the measure"
}
]
}
